function skillEdges(m){if(['register','vote','reserve','thief'].includes(m.kind))return [];let sources=actorIds();if(m.kind==='shot'||m.kind==='whiteTake')sources=[viewState().pending[0]?.id];else if(m.kind==='badge')sources=[viewState().sheriff];else if(m.kind==='whiteAction'&&viewState().white?.action?.kind==='duel')sources=[viewState().white.action.actor];else if(m.kind.endsWith('Action'))return [];sources=[...new Set(sources.filter(id=>player(id)))];const edges=[];for(const a of m.actions){const target=draftValue(a);if(!target||!player(target))continue;for(const source of sources)edges.push({source,target,field:a.field,active:a===currentAction(m)});}return edges;}
