function voteTrayMarkup(m){const done=m.voters.filter(p=>viewState().votes[p.id]!==undefined&&viewState().votes[p.id]>=0).length;return `<div class="vote-meter"><span>第 ${viewState().voteRound} 輪 · ${m.elect?'警長競選':'放逐投票'}</span><strong>${done} / ${m.voters.length} 已記錄</strong><progress value="${done}" max="${Math.max(1,m.voters.length)}" aria-label="投票記錄進度"></progress></div>${votePriorRoundMarkup()}<div class="voter-line" aria-label="選擇或修改投票者">${m.voters.map(p=>{const voted=viewState().votes[p.id]!==undefined&&viewState().votes[p.id]>=0;return `<button class="voter ${g.voter===p.id?'on':''} ${voted?'recorded':''}" onclick="selectVoteVoter(${p.id})" aria-pressed="${g.voter===p.id}" aria-label="${p.id} 號投票者，${voteStatus(p.id)}"><b>${p.id}</b><span>${voted?viewState().votes[p.id]===0?'棄票':'→ '+viewState().votes[p.id]:'待投'}</span></button>`}).join('')}</div>${m.elect?sheriffTray(m):''}`}
function voteFocusMarkup(m){const recorded=viewState().votes[g.voter]!==undefined&&viewState().votes[g.voter]>=0;return `<div class="vote-focus"><small>${voteComplete(m)?'全部票已記錄':recorded?'修改已記錄的票':'正在記錄投票'}</small><div><span><b>${g.voter||'—'}</b><em>號投票者</em></span><i>→</i><span><b class="vote-destination">${recorded?viewState().votes[g.voter]===0?'棄':viewState().votes[g.voter]:'？'}</b><em>${recorded?viewState().votes[g.voter]===0?'已棄票':'號對象':'尚未記錄'}</em></span></div></div>`}
function voteReceiptMarkup(m){if(!lastVoteReceipt){const done=m.voters.filter(p=>viewState().votes[p.id]!==undefined&&viewState().votes[p.id]>=0).length;return `<div class="vote-receipt ${done?'':'receipt-empty'}" role="status" aria-live="polite"><span>${done?'已恢復 '+done+'／'+m.voters.length+' 票':'尚未記錄投票'}${done?`<small>${voteComplete(m)?'可以揭曉票數':'請繼續記錄剩餘票數'}</small>`:''}</span></div>`;}const r=lastVoteReceipt;return `<div class="vote-receipt" role="status" aria-live="polite"><span>已記錄 <b>${r.voter} 號 → ${r.target?r.target+' 號':'棄票'}</b>${!voteComplete(m)?`<small>${g.voter===r.voter?'正在修改這一票':'目前 '+g.voter+' 號待記錄'}</small>`:'<small>可以揭曉票數</small>'}</span><button onclick="selectVoteVoter(${r.voter})">修改這一票</button></div>`}
function selectionSummary(m){
 if(m.kind!=='register'&&!m.actions.length)return '';
 let items=[];
 if(m.kind==='register')items=currentReg().map((r,i)=>g.regs[i]?`<span>${esc(r)} <b>${g.regs[i]} 號</b></span>`:'');
 else if(m.gifts){const d=viewState().draft;items=[`<span>交易對象 <b>${d.trade?d.trade+' 號':'尚未選擇'}</b></span>`,`<span>贈送技能 <b>${esc(d.gift||'尚未選擇')}</b></span>`];}
 else if(m.kind==='shot'&&g.shotMode==='skip')items=['<span>開槍處置 <b>放棄開槍</b></span>'];
 else if(m.kind==='badge'&&g.badgeMode==='destroy')items=['<span>警徽處置 <b>撕毀警徽</b></span>'];
 else items=m.actions.filter(a=>draftValue(a)).map(a=>`<span>${esc(a.name)} <b>→ ${draftValue(a)} 號</b></span>`);
 return `<div class="choice-receipt ${items.some(Boolean)?'':'receipt-empty'}" role="status" aria-live="polite">${items.some(Boolean)?items.join(''):'<span>尚未選擇</span>'}</div>`;
}
function introMarkup(m){const roles=portraitsFor(m),title=currentReg()?roles.join('／')+' · 認牌':m.title;return `<div class="intro-backdrop"></div><section class="role-intro ${graphicPlayMode(m)?'graphic-play':''}" role="dialog" aria-modal="true" aria-labelledby="role-intro-title"><div class="intro-scroll"><div class="intro-art ${roles.length>1?'duet':''}">${roles.map(r=>portrait(r)).join('')}</div><div class="intro-copy"><span class="intro-chapter">${esc(m.eyebrow)}</span><span class="intro-label">本回合</span><h2 id="role-intro-title">${esc(title)}</h2>${viewState().phase==='night'?'<span class="call-label">朗讀口令</span>':''}<p class="intro-call">${esc(m.line)}</p>${victoryForecastMarkup()}${hunterStatusMarkup(m.hunterStatus)}${m.detail?`<p class="intro-note">${esc(m.detail)}</p>`:''}${viewState().flowNotice?`<p class="intro-note">${esc(viewState().flowNotice)}</p>`:''}</div></div><footer class="intro-footer"><button id="begin-role" class="commit-btn" onclick="closeRoleIntro()">進入回合 ${icon('check')}</button></footer></section>`}
function hunterStatusMarkup(st){if(!st)return '';return `<div class="hunter-status ${st.available?'ready':'blocked'}" role="status"><span>${icon('gun')}<small>明早技能狀態</small></span><strong>${st.id&&role('獵人')?.alive?(st.available?'可以開槍':'不可以開槍'):esc(st.reason)}</strong><small>${esc(st.note)}</small></div>`;}
function dawnResultsMarkup(m){return `<div class="dawn-results" role="status" aria-live="polite"><small>昨夜結果</small>${m.dead.length?`<div class="dawn-dead-list">${m.dead.map(id=>`<span><b>${String(id).padStart(2,'0')}</b><small>${esc(player(id)?.name||'號玩家')}</small></span>`).join('')}</div>`:'<strong>平安夜</strong>'}</div>`;}
function exileDeaths(r){
 // Start at the vote transaction. Older deaths and later night deaths do not
 // belong to this exile batch; a legacy save without a cursor stays conservative.
 const offset=r.deathEventId;if(!Number.isInteger(offset))return [];
 return GameEngine.events().filter(e=>e.id>offset&&e.type==='death'&&e.round===r.n&&e.phase==='day');
}
function voteResultMarkup(){const st=viewState(),r=st.voteResult;if(!r||r.n!==st.n)return '';
 if(r.elect?st.phase!=='dawn':!(st.phase==='day'&&st.voteDone&&r.outcome!=='pk'))return '';
 if(st.pending.length||st.badge)return '';
 const chips=Object.entries(r.tally||{}).filter(([,n])=>n>0).sort((a,b)=>b[1]-a[1]||a[0]-b[0]).map(([id,n])=>`${id} 號 ${n} 票`).join('／');
 const abstains=Object.values(r.ballots||{}).filter(t=>!t).length;
 const title=r.elect?'警長結果':'放逐結果';
 const outcome=r.elect?(r.outcome==='elected'?`${r.target} 號當選警長`:r.outcome==='unopposed'?`唯一候選人 · ${r.target} 號當選警長`:'警徽流失'):(r.outcome==='exiled'?(st.board==='classic'&&player(r.target)?.alive&&player(r.target)?.idiotRevealed?`${r.target} 號白痴翻牌 · 仍存活`:`${r.target} 號被放逐`):'無人放逐');
 const deaths=!r.elect&&r.outcome==='exiled'?exileDeaths(r):[];
 const details=deaths.length?`<div class="vote-deaths"><small>本次出局 · ${deaths.length} 人</small>${deaths.map(e=>`<span><b>${e.player} 號</b><small>${esc(e.factors.map(f=>f.label).join('、'))}</small></span>`).join('')}</div>`:'';
 return `<div class="vote-results" role="status" aria-live="polite"><small>${title}${r.round>1?' · 第 '+r.round+' 輪':''}</small><strong>${esc(outcome)}</strong>${chips?`<span class="vote-tally">${esc(chips)}${abstains?` · 棄 ${abstains} 票`:''}</span>`:''}${r.note?`<span class="vote-note">${esc(r.note)}</span>`:''}${details}</div>`;}
function votePriorRoundMarkup(){const st=viewState(),r=st.voteResult;if(!r||r.outcome!=='pk'||r.n!==st.n||st.voteRound!==2)return '';
 const chips=Object.entries(r.tally||{}).filter(([,n])=>n>0).sort((a,b)=>b[1]-a[1]||a[0]-b[0]).map(([id,n])=>`${id} 號 ${n} 票`).join('／');
 return `<div class="vote-prior" role="status">上一輪${r.elect?'警長':''}投票${chips?`：${esc(chips)}`:''} · 平票，進入 PK</div>`;}
const uxPriorNightUI=nightUI;
nightUI=function(){if(viewState().phase!=='night'||nightSteps()[viewState().step]!=='hunter'||currentReg())return uxPriorNightUI();const m=nightModel();return `<h2>${m.title}</h2><p class="callout">${m.line}</p>${victoryForecastMarkup()}${hunterStatusMarkup(m.hunterStatus)}<p class="tiny">${esc(m.detail)}</p><div class="footerbar"><button onclick="backNight()" ${!viewState().step?'disabled':''}>上一步</button><button class="primary" onclick="nextNight()">${m.confirm}</button></div>`;};

// Board browsing is presentation state. Only confirmation selects the engine template.
let setupBoardFocus=null,galleryDetail=null,gallerySuppressClickUntil=0;
const BOARD_STORIES={
 classic:{art:['預言家','白痴'],tag:'經典十二人',text:'四隻普通狼人，對上預言家、女巫、獵人與白痴。白痴首次放逐翻牌仍存活，可發言但無投票權，仍計入神邊；刀、毒、槍正常致死。'},
 brothers:{art:['狼兄','狼弟','黑市商人'],tag:'血脈與交易',text:'狼兄與狼弟的復仇時序，遇上黑市商人的一次交易。掌握傳承與贈禮，改變村莊的命運。'},
 mechanical:{art:['機械狼','通靈師'],tag:'學習與偽裝',text:'機械狼獨自行動，學習他人的身分與能力；通靈師查驗具體身分，追尋偽裝背後的真相。'},
 gargoyle:{art:['石像鬼','守墓人'],tag:'暗處的觀察者',text:'石像鬼暗中查驗身分，等待繼承狼刀；守墓人從被放逐者的陣營，拼出白天留下的線索。'},
 whiteknight:{art:['白狼王','騎士'],tag:'白晝的對決',text:'騎士以決鬥揭開身分，白狼王在符合條件的出局時帶走一人。每次白天交鋒，都可能改寫局勢。'},
 bloodmoon:{art:['血月使者','獵魔人'],tag:'血月下的狩獵',text:'血月使者自爆後封印下一夜的好人技能；獵魔人以生命為賭注，尋找真正的狼人。'},
 dream:{art:['夢魘','攝夢人'],tag:'恐懼與夢境',text:'夢魘以恐懼阻斷行動，攝夢人讓玩家進入夢遊。庇護與牽連，取決於每一晚的選擇。'},
 cupid:{art:['盜賊','丘比特'],tag:'命運與羈絆',text:'盜賊選擇新的身分，丘比特連結兩位戀人。當人與狼相戀，第三方將為自己的勝利而戰。'}
};
function galleryBoardIds(){return ['brothers','mechanical','gargoyle','whiteknight','bloodmoon','dream','cupid','classic']}
function boardComposition(id,variant=id===viewState().board?viewState().variant:'standard12'){const counts=new Map();for(const role of boardConfiguration(id,variant).roles)counts.set(role,(counts.get(role)||0)+1);return [...counts].map(([r,n])=>`${r}${n>1?' × '+n:''}`).join(' · ')}
function galleryMove(index,instant=false){const track=document.getElementById('board-track'),cards=track?.querySelectorAll('.board-slide');if(!cards?.length)return;index=Math.max(0,Math.min(cards.length-1,index));const rect=track.getBoundingClientRect(),card=cards[index].getBoundingClientRect();track.scrollTo({left:track.scrollLeft+card.left-rect.left-(rect.width-card.width)/2,behavior:instant||!presentationMotionAllowed()?'instant':'smooth'});}
function gallerySync(){const track=document.getElementById('board-track');if(!track)return;const mid=track.getBoundingClientRect().left+track.clientWidth/2;const cards=[...track.querySelectorAll('.board-slide')];let best=0,dist=Infinity;cards.forEach((el,i)=>{const r=el.getBoundingClientRect(),d=Math.abs(r.left+r.width/2-mid);if(d<dist){dist=d;best=i}});setupBoardFocus=galleryBoardIds()[best];primeRoleImages();document.getElementById('gallery-count').textContent=`${String(best+1).padStart(2,'0')} / ${String(galleryBoardIds().length).padStart(2,'0')}`;document.getElementById('gallery-selected').textContent=BOARD_TEMPLATES[setupBoardFocus].label;document.querySelectorAll('.gallery-dot').forEach((el,i)=>{el.classList.toggle('active',i===best);el.setAttribute('aria-current',i===best?'true':'false')});document.getElementById('gallery-prev').disabled=best===0;document.getElementById('gallery-next').disabled=best===cards.length-1;}
let galleryVariant='standard12';
function chooseGalleryVariant(variant){if(viewState().phase!=='setup'||galleryDetail!=='brothers'||!['standard12','wolfking10'].includes(variant))return;portraitPreparation++;galleryVariant=variant;primeRoleImages();render();}
function galleryConfirm(rulesOnly=false){if(viewState().phase!=='setup')return;const id=galleryDetail||setupBoardFocus||viewState().board,variant=galleryDetail?galleryVariant:id===viewState().board?viewState().variant:'standard12';const proceed=()=>{galleryDetail=null;if(rulesOnly){openHostDrawer('engine')}else confirmGame();};if(id!==viewState().board||variant!==viewState().variant){GameEngine.configure(id,variant,proceed);}else proceed()}

function galleryOpen(id,event){if(event?.detail&&Date.now()<gallerySuppressClickUntil)return;portraitPreparation++;setupBoardFocus=id;galleryDetail=id;galleryVariant=id===viewState().board?viewState().variant:'standard12';render()}
function galleryClose(){portraitPreparation++;galleryDetail=null;render();requestAnimationFrame(()=>document.querySelectorAll('.board-open')[galleryBoardIds().indexOf(setupBoardFocus)]?.focus({preventScroll:true}))}
function galleryDetailMarkup(){if(!galleryDetail||gDrawer)return '';const id=galleryDetail,t=BOARD_TEMPLATES[id],story=BOARD_STORIES[id],config=boardConfiguration(id,galleryVariant);return `<dialog id="gallery-dialog" class="gallery-dialog" aria-labelledby="gallery-dialog-title" oncancel="event.preventDefault();galleryClose()" onclick="if(event.target===this)galleryClose()"><div class="gallery-dialog-inner"><header><span>板子詳情</span><button class="gallery-close" aria-label="關閉板子詳情" onclick="galleryClose()">${icon('x')}</button></header><div class="gallery-detail-body"><div class="board-art art-${story.art.length}">${story.art.map(r=>`<div>${portrait(r)}<span>${r}</span></div>`).join('')}</div><div class="board-copy"><span class="board-tag">${story.tag}</span><h2 id="gallery-dialog-title">${t.title}<em>／ ${t.subtitle}</em></h2><p>${story.text}</p><section class="board-composition">${id==='brothers'?`<label for="gallery-variant">人數與配置</label><select id="gallery-variant" onchange="chooseGalleryVariant(this.value)">${['standard12','wolfking10'].map(v=>`<option value="${v}" ${galleryVariant===v?'selected':''}>${boardConfiguration(id,v).label}</option>`).join('')}</select>`:''}<h3>角色配置 · ${id==='cupid'?'14 張牌，12 人入席':config.playerCount+' 人'}</h3><p>${boardComposition(id,galleryVariant)}</p>${galleryVariant==='wolfking10'?'<p>普通狼王非中毒、非自爆出局且勝負未定時可開一槍；狼隊環節認牌，不設報槍。其餘規則與夜序沿用 12 人版。</p>':''}${id==='cupid'?'<p>2 張盜賊備選牌；盜賊、丘比特必須發給玩家。</p>':''}</section></div></div><footer><button class="commit-btn" onclick="prepareGalleryGame(this)">確認使用 · 開始認牌 ${icon('check')}</button><button class="gallery-settings" onclick="galleryConfirm(true)">規則與玩家暱稱</button></footer></div></dialog>`}
function galleryGestureAxis(dx,dy){if(Math.max(Math.abs(dx),Math.abs(dy))<10)return '';if(Math.abs(dx)>Math.abs(dy)*1.25)return 'x';if(Math.abs(dy)>Math.abs(dx)*1.25)return 'y';return ''}
function bindGalleryGestures(track){if(track.getAttribute?.('data-keyboard-bound'))return;track.setAttribute?.('data-keyboard-bound','true');let drag=null;
 track.addEventListener('pointerdown',e=>{if(!e.isPrimary||e.button!==0)return;drag={native:e.pointerType==='touch'||e.pointerType==='pen',id:e.pointerId,x:e.clientX,y:e.clientY,left:track.scrollLeft,index:galleryBoardIds().indexOf(setupBoardFocus),axis:'',dx:0,moved:false}});
 track.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;drag.dx=dx;if(Math.max(Math.abs(dx),Math.abs(dy))>=10){drag.moved=true;gallerySuppressClickUntil=Date.now()+500}if(drag.native)return;if(!drag.axis)drag.axis=galleryGestureAxis(dx,dy);if(drag.axis==='x'){if(e.cancelable)e.preventDefault();track.setPointerCapture(e.pointerId);track.classList.add('dragging');track.scrollLeft=drag.left-dx}});
 const finish=e=>{if(!drag||drag.id!==e.pointerId)return;const d=drag;drag=null;track.classList.remove('dragging');if(d.moved||e.type==='pointercancel')gallerySuppressClickUntil=Date.now()+500;if(!d.native&&d.axis==='x'){if(track.hasPointerCapture(e.pointerId))track.releasePointerCapture(e.pointerId);const shift=e.type==='pointercancel'?0:Math.abs(d.dx)>Math.min(60,track.clientWidth*.15)?(d.dx<0?1:-1):0;galleryMove(d.index+shift)}};
 track.addEventListener('pointerup',finish);track.addEventListener('pointercancel',finish);track.addEventListener('lostpointercapture',finish);
 // Native touch scrolling owns momentum and snapping; never capture or cancel it.
 track.addEventListener('scroll',()=>{gallerySuppressClickUntil=Date.now()+250},{passive:true});
 track.addEventListener('click',e=>{if(e.detail&&Date.now()<gallerySuppressClickUntil){e.preventDefault();e.stopImmediatePropagation()}},true);
}

function renderBoardGallery(){
 introOpen=false;
 const ids=galleryBoardIds(),active=setupBoardFocus||viewState().board;setupBoardFocus=active;const index=ids.indexOf(active);document.body.dataset.light='dusk';
 cancelAnimationFrame(sceneFrame);sceneResize?.disconnect();updatePresentation(`<main class="board-gallery" ${gDrawer?'inert':''}><header class="gallery-header"><span>${icon('moon')} Aurawolf｜全知之人</span><small class="beta-badge" aria-label="Beta 測試版本">Beta</small></header><div class="gallery-heading"><span>CHOOSE YOUR STORY</span><h1>今晚，展開哪一段故事？</h1></div><section id="board-track" class="board-track" aria-label="選擇板子" aria-roledescription="輪播" tabindex="0">${ids.map((id,i)=>{const t=BOARD_TEMPLATES[id],story=BOARD_STORIES[id];return `<article class="board-slide" aria-label="${i+1} / ${ids.length}：${t.label}" aria-roledescription="投影片"><button class="board-open" onclick="galleryOpen('${id}',event)" aria-label="查看${t.label}詳情"><div class="board-art art-${story.art.length}">${story.art.map(r=>`<div>${portrait(r)}<span>${r}</span></div>`).join('')}</div><div class="board-copy"><span class="board-tag">${story.tag}</span><h2>${t.title}<em>／ ${t.subtitle}</em></h2><p class="board-teaser">${story.tag}</p><span class="board-open-label">查看板子 ${icon('eye')}</span></div></button></article>`}).join('')}</section><footer class="gallery-footer"><div class="gallery-navigation"><button id="gallery-prev" aria-label="上一個板子" onclick="galleryMove(galleryBoardIds().indexOf(setupBoardFocus)-1)" ${index===0?'disabled':''}>←</button><div class="gallery-dots">${ids.map((id,i)=>`<button class="gallery-dot ${id===active?'active':''}" aria-label="選擇${BOARD_TEMPLATES[id].label}" aria-current="${id===active}" onclick="galleryMove(${i})"></button>`).join('')}</div><button id="gallery-next" aria-label="下一個板子" onclick="galleryMove(galleryBoardIds().indexOf(setupBoardFocus)+1)" ${index===ids.length-1?'disabled':''}>→</button></div><div class="gallery-choice" aria-live="polite"><span id="gallery-count">${String(index+1).padStart(2,'0')} / ${String(ids.length).padStart(2,'0')}</span><strong id="gallery-selected">${BOARD_TEMPLATES[active].label}</strong></div></footer></main>${galleryDetailMarkup()}${showDrawer()}<div id="engine-pane" ${gDrawer==='engine'?'':'hidden'}>${mainUI()}</div>`);
 if(gDrawer==='engine')document.getElementById('engine-slot').append(document.getElementById('engine-pane'));mountPortraits();mountHostDrawer();const track=document.getElementById('board-track');if(!track.getAttribute?.('data-keyboard-bound')){track.addEventListener('scroll',gallerySync,{passive:true});track.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();galleryMove(galleryBoardIds().indexOf(setupBoardFocus)+(e.key==='ArrowRight'?1:-1))}});}bindGalleryGestures(track);requestAnimationFrame(()=>galleryMove(index,true));const dialog=document.getElementById('gallery-dialog');if(galleryDetail&&!gDrawer&&dialog){if(!dialog.open)dialog.showModal?.();if(!dialog.contains?.(document.activeElement))dialog.querySelector?.('.gallery-close')?.focus()}
 finishPresentation('setup:false:-1');
}


let detailPlayerId=0,hostLogPeriod='',hostNoteDraft='';
const SKILL_LABELS={knife:'狼刀',revenge:'復仇刀',inspectAlignment:'查驗陣營',inspectRole:'查驗身分',heal:'解藥',poison:'毒藥',guard:'守護',shoot:'開槍',trade:'黑市交易',learn:'學習',inspectExile:'查驗放逐者',take:'帶走玩家',duel:'決鬥',bloodSeal:'血月封印',lastNight:'最後黑夜',hunt:'狩獵',fear:'恐懼',dream:'攝夢',swap:'換牌',link:'連結戀人',reveal:'翻牌',learnedInspectRole:'學習・查驗',learnedPoison:'學習・毒藥',learnedGuard:'學習・守護',learnedShoot:'學習・開槍',doubleKnife:'雙刀',gift查驗:'贈禮・查驗',gift毒藥:'贈禮・毒藥',gift獵槍:'贈禮・獵槍'};
const EFFECT_LABELS={fear:'恐懼',seal:'血月封印',guard:'守護',mechanicalGuard:'機械守護',dream:'夢遊'};
function mountHostDrawer(){const drawer=document.querySelector('.game-drawer');if(!drawer)return;const controls=()=>[...drawer.querySelectorAll('button:not(:disabled),select,textarea,input,a[href],summary')].filter(el=>el.getClientRects().length);if(!drawer.contains?.(document.activeElement))controls()[0]?.focus({preventScroll:true});if(drawer.getAttribute?.('data-keyboard-bound'))return;drawer.setAttribute?.('data-keyboard-bound','true');drawer.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();closeHostDrawer();return}if(e.key==='Tab'){const list=controls(),first=list[0],last=list[list.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}})}
function closeHostDrawer(){gDrawer='';drawerNavigation='';render();if(drawerReturnFocus?.isConnected)drawerReturnFocus.focus({preventScroll:true});}
function openHostDrawer(kind){const menu=document.getElementById('hud-menu'),toggle=document.querySelector('.hud-menu-toggle');if(!gDrawer)drawerReturnFocus=menu?.open&&toggle?.getClientRects?.().length?toggle:document.activeElement;else if(kind!==gDrawer||detailPlayerId)drawerNavigation='tab';closeHudMenu();gDrawer=kind;detailPlayerId=0;if(kind==='atlas')atlasRole='';if(kind==='engine')tab='play';render();}
function openRoleDetail(id){if(!viewState().players.some(p=>p.id===id))return;if(gDrawer==='seats'&&!detailPlayerId){rosterScroll=document.querySelector('.drawer-body')?.scrollTop||0;rosterReturnFocus=document.activeElement;drawerNavigation='forward';}else if(!gDrawer)drawerReturnFocus=document.activeElement;detailPlayerId=id;gDrawer='seats';render();const body=document.querySelector('.drawer-body');if(body)body.scrollTop=0;document.querySelector('.detail-back')?.focus({preventScroll:true});}
function returnToRoster(){detailPlayerId=0;drawerNavigation='back';render();const body=document.querySelector('.drawer-body');if(body)body.scrollTop=rosterScroll;const id=rosterReturnFocus?.getAttribute?.('onclick');const target=id?[...document.querySelectorAll('.host-roster button')].find(el=>el.getAttribute('onclick')===id):null;target?.focus({preventScroll:true});}
function detailSection(title,body){return `<section class="detail-section"><h3>${title}</h3>${body}</section>`}
function hostRosterMarkup(){return `<p class="drawer-sub">${alive().length} / ${viewState().players.length} 存活 · 點選玩家查看詳情</p>${isCupid()?cupidRosterSummary():''}<div class="host-roster">${GameEngine.roles().map(r=>{const p=player(r.id);return `<button onclick="openRoleDetail(${r.id})"><b>${String(r.id).padStart(2,'0')}</b><span>${esc(p.name||'玩家 '+r.id)}<small>${esc(r.currentRole)} · ${r.life==='delayedDeath'?'延後死亡':r.alive?'存活':'已出局'}${r.id===viewState().sheriff?' · 警長':''}</small></span><i>›</i></button>`}).join('')}</div>`}
function skillDetailText(k,r){const out=[];
 if(k.id==='revenge'&&r.progression==='waiting')out.push('尚未覺醒');else if(k.remaining!==null)out.push(k.remaining===0?'剩餘 0 次':'剩餘 '+k.remaining+' 次');else out.push('依回合與條件發動');
 if(k.availableFrom&&k.availableFrom>viewState().n)out.push('第 '+k.availableFrom+' 夜起生效');
 if(k.requires&&!k.enabled&&r.alive)out.push('尚未取得獨立狼刀');
 if(k.blockedBy?.length)out.push(k.blockedBy.map(x=>EFFECT_LABELS[x]||'限制效果').join('、'));
 if(k.previousTarget)out.push('上次目標 '+k.previousTarget+' 號');
 if(['shoot','learnedShoot','gift獵槍','take','lastNight'].includes(k.id))out.push('出局時依死因與規則判定');
 if(!r.alive)out.push('已出局');return out.join(' · ')
}
function knowledgeText(k){const result=k.result;if(k.kind==='gunStatus'&&result&&typeof result==='object')return `獵人狀態：${result.available?'可以開槍':'不能開槍'}${result.reason?'（'+result.reason+'）':''}`;if(k.kind==='loverSeat')return '戀人：'+result+' 號';return `${k.target?k.target+' 號 · ':''}${typeof result==='string'||typeof result==='number'?result:'已確認資訊'}`}
function roleDetailMarkup(id){const r=GameEngine.role(id),p=player(id);if(!r||!p)return hostRosterMarkup();
 let body=`<button class="detail-back" onclick="returnToRoster()">← 返回名冊</button><div class="player-profile">${r.registered?portrait(r.currentRole):`<div class="unknown-portrait">${icon('person')}</div>`}<div><small>${String(id).padStart(2,'0')} 號 · ${esc(p.name||'玩家 '+id)}</small><h3>${esc(r.currentRole)}</h3><p>${r.life==='delayedDeath'?'延後死亡':r.alive?'存活':'已出局'}${id===viewState().sheriff?' · 警長':''}</p></div></div>`;
 if(!r.registered)return body+'<p class="drawer-sub">等待第一夜睜眼認牌；目前不推定陣營或技能。</p>';
 const info=[['勝利陣營',r.alignment],['屠邊歸屬',({wolf:'狼邊',god:'神邊',villager:'民邊',other:'特殊角色',unknown:'未知'})[r.edge]],['原始身分',r.originalRole],['發言資格',r.canSpeak?'保有':'無'],['本輪投票資格',r.canVote?'保有':'無']];
 body+=detailSection('身分與資格',`<dl class="role-facts">${info.map(([a,b])=>`<div><dt>${a}</dt><dd>${esc(b)}</dd></div>`).join('')}</dl>`);
 if(r.pendingAbilities.length)body+=detailSection('待處理技能',r.pendingAbilities.map(k=>`<p class="pending-detail">${SKILL_LABELS[k.id]||'出局技能'}${k.remaining?' · 剩餘 '+k.remaining+' 次':''}</p>`).join(''));
 body+=detailSection('技能與資源',r.skills.length?`<ul class="role-list">${r.skills.map(k=>`<li><strong>${SKILL_LABELS[k.id]||'特殊技能'}</strong><small>${esc(skillDetailText(k,r))}</small></li>`).join('')}</ul>`:'<p>無主動技能。</p>');
 if(r.learned)body+=detailSection('學習紀錄',`<p>第 ${r.learned.night} 夜 · ${r.learned.id} 號 · ${esc(r.learned.role)}</p><p>目前查驗回報：${esc(r.inspectionRole)}</p>`);
 if(r.progression)body+=detailSection('狼弟進程',`<p>${({waiting:'尚未覺醒',revenge:'本夜使用復仇刀；下一夜加入狼隊',joined:'已加入狼隊共同刀人'})[r.progression]}</p>`);
 body+=detailSection('目前效果',r.effects.length?`<ul class="role-list">${r.effects.map(e=>`<li><strong>${EFFECT_LABELS[e.kind]||'特殊效果'}${e.repeat?' · 連續攝夢':''}</strong><small>${e.source?'來源 '+e.source+' 號 · ':''}第 ${e.starts.round} 夜，至夜間結算${e.blocks?' · 防禦'+e.blocks.map(x=>x==='knife'?'狼刀':'毒藥').join('、'):''}</small></li>`).join('')}</ul>`:'<p class="detail-empty">目前沒有記錄中的暫時效果。</p>');
 body+=detailSection('角色關係',r.relationships.length?`<ul class="role-list">${r.relationships.map(x=>`<li><strong>${({lovers:'戀人',siblings:'兄弟',dreamLink:'攝夢連結'})[x.kind]||'角色關係'}</strong><small>${x.targets.map(n=>esc(who(n))).join('、')}${x.source?' · 來源 '+x.source+' 號':''}</small></li>`).join('')}</ul>`:'<p class="detail-empty">無已記錄關係。</p>');
 if(r.death)body+=detailSection('出局紀錄',`<p>第 ${r.death.round} ${r.death.phase==='night'?'夜':'天'}${r.death.legacy?' · 舊紀錄':''}</p><p>${r.death.factors.map(f=>esc(f.label)).join(' ＋ ')||'死因未記錄'}</p>`);
 body+=detailSection('已告知資訊',r.knowledge.length?`<ul class="role-list">${r.knowledge.slice().reverse().map(k=>`<li><strong>${esc(knowledgeText(k))}</strong><small>第 ${k.round} ${k.phase==='night'?'夜':'天'}</small></li>`).join('')}</ul>`:'<p class="detail-empty">尚無已確認告知的紀錄。</p>');return body;
}
function hostLogMarkup(){const logs=viewState().logs,periods=[...new Set(logs.map(l=>l.period))].reverse();if(hostLogPeriod&&!periods.includes(hostLogPeriod))hostLogPeriod='';const entries=logs.slice().reverse().filter(l=>!hostLogPeriod||l.period===hostLogPeriod);let prior='';return `<div class="log-tools"><label>查看階段<select aria-label="篩選紀錄階段" onchange="hostLogPeriod=this.value;render()"><option value="">全部階段</option>${periods.map(p=>`<option value="${esc(p)}" ${hostLogPeriod===p?'selected':''}>${esc(p)}</option>`).join('')}</select></label><button onclick="download()">匯出完整紀錄</button></div><details class="host-section"><summary>新增主持筆記</summary><textarea id="game-note" placeholder="發言、爭議或現場裁定…" oninput="hostNoteDraft=this.value">${esc(hostNoteDraft)}</textarea><button onclick="saveHostNote()">加入紀錄</button></details><p class="drawer-sub">${entries.length} 筆 · 最新在前</p><div class="story-list">${entries.length?entries.map(l=>{const head=l.period!==prior?`<h3>${esc(l.period)}</h3>`:'';prior=l.period;return head+`<article><small>${esc(l.at)}</small><p>${esc(logText(l))}</p></article>`}).join(''):'<p>尚無這個階段的紀錄。</p>'}</div>`}
function saveHostNote(){const text=hostNoteDraft.trim();if(!text)return;hostNoteDraft='';GameEngine.note(text);render()}
function hostManagementMarkup(){return `<p class="drawer-sub">版本 ${esc(document.querySelector('meta[name="application-version"]')?.content||'開發版')} · ${esc(boardLabel())} · ${saveError?'存檔失敗，請先匯出紀錄':'進度自動儲存在此瀏覽器'}</p><section class="host-section"><h3>發言計時</h3><div class="host-timer" id="timer">${timeText()}</div><div class="timer-controls"><button onclick="ticking=!ticking;render()">${ticking?'暫停':'開始'}</button><button onclick="timer=90;ticking=false;render()">重設 90 秒</button><select aria-label="計時長度" onchange="timer=Number(this.value);ticking=false;render()"><option value="" disabled selected>選擇時長</option>${[60,90,120,180].map(n=>`<option value="${n}">${n} 秒</option>`).join('')}</select></div></section><details class="host-section"><summary>本局配置與規則摘要</summary><p>${esc(boardComposition(viewState().board))}</p><p>${esc(rulesText(viewState().rules,viewState().board))}</p><p>${esc(BOARD_STORIES[viewState().board].text)}</p></details><details class="host-section" ${viewState().phase==='setup'?'open':''}><summary>${viewState().phase==='setup'?'開局設定 · 規則與暱稱':'本回合操作與修正'}</summary><div id="engine-slot"></div></details><div class="drawer-foot"><button onclick="undo()" ${viewState().canUndo?'':'disabled'}>撤回上一個已確認操作</button><button onclick="download()">匯出完整紀錄</button></div><div class="new-game-zone"><button onclick="resetFromManagement()">結束本局並開新局</button></div>`}


let mobileRenderKey='';
function restorePlayScroll(key,top){const el=document.querySelector('.play-scroll');if(el)el.scrollTop=key===mobileRenderKey||key.split(':').slice(0,-2).join(':')===mobileRenderKey.split(':').slice(0,-2).join(':')?top:0;mobileRenderKey=key}
function installMobileViewport(){
 if(!window.addEventListener||!document.documentElement)return;
 const update=()=>{const vv=window.visualViewport;if(vv&&vv.scale>1.05)return;const height=vv?.height||window.innerHeight;document.documentElement.style.setProperty('--app-height',height+'px');document.documentElement.style.setProperty('--app-top',(vv?.offsetTop||0)+'px');if(document.activeElement?.matches?.('input,textarea,select'))requestAnimationFrame(()=>document.activeElement?.scrollIntoView?.({block:'nearest',inline:'nearest'}))};
 window.addEventListener('resize',update,{passive:true});window.visualViewport?.addEventListener('resize',update,{passive:true});window.visualViewport?.addEventListener('scroll',update,{passive:true});update();
}
installMobileViewport();

// UI state and rules use the existing hosted game save.
primeRoleImages();render();
